validator:
function validate(input) {
  const [{ Department = [] }] = input;
  const months = new Set(['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']);
  const keys = new Set();
  for (const [id, , month] of Department) {
    if (id === null || month === null) return 'id and month may not be null.';
    if (!months.has(month)) return `month ${month} is not one of Jan..Dec.`;
    const key = `${id}|${month}`;
    if (keys.has(key)) return `Department ${id} has two rows for ${month}.`;
    keys.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const ids = small ? [1, 2, 3, 7] : Array.from({ length: 160 }, (_, i) => i + 1);
  const limit = small ? Math.floor(rand() * 9) : 2000;
  // Each department gets a random set of months; small cases keep the pool short so departments share months.
  const pool = small ? months.slice(0, 4 + Math.floor(rand() * 9)) : months;
  const Department = [];
  for (const id of ids) {
    for (const month of pool) {
      if (Department.length >= limit) break;
      if (rand() < (small ? 0.35 : 0.85)) {
        const revenue = rand() < 0.1 ? 0 : (small ? 1000 * (1 + Math.floor(rand() * 12)) : Math.floor(rand() * 50000));
        Department.push([id, revenue, month]);
      }
    }
  }
  // Store rows in a shuffled order, as a real table would be.
  for (let i = Department.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Department[i], Department[j]] = [Department[j], Department[i]]; }
  return [{ Department }];
}
